// make.fun entry: "Sum up 25 November's world news in one image"
// A newspaper front page for Wednesday 25 November 2026, drawn by hand as
// HTML/CSS/SVG in entry.html and rendered to PNG in this session: 55 dated,
// verified stories across 10 regions, 16 hand-drawn scenes, a world map with
// pins, a UTC timeline, "how sure" labels and a date check. The PNG was
// optimised to a 256-colour palette (149,020 bytes) without losing legibility.
// The PNG bytes are embedded below (base64, one line) so the program is fully
// self-contained: Node 22 standard library only, no network, deterministic.
// It writes the image to <output>/entry.png (MAKEFUN_OUTPUT_DIR or /output).
import { createHash } from "node:crypto";
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const IMAGE_B64 = "";
const IMAGE_SHA256 = "7658ef1a1d0a9b7f4bbd04b056b7755c0bbf21cfa4af74b2391f3cca5f66366d";

const outDir = process.env.MAKEFUN_OUTPUT_DIR ?? "/output";
const png = Buffer.from(IMAGE_B64, "base64");
if (png.length === 0 || png.length > 1048576) {
  throw new Error(`entry.png must be 1..1048576 bytes, got ${png.length}`);
}
if (png[0] !== 0x89 || png[1] !== 0x50 || png[2] !== 0x4e || png[3] !== 0x47) {
  throw new Error("embedded image is not a PNG");
}
const digest = createHash("sha256").update(png).digest("hex");
if (digest !== IMAGE_SHA256) {
  throw new Error(`embedded image sha256 mismatch: got ${digest}`);
}
mkdirSync(outDir, { recursive: true });
writeFileSync(join(outDir, "entry.png"), png);
console.log(`wrote entry.png (${png.length} bytes, sha256 ${digest.slice(0, 12)}...)`);
